package main

import (
	"context"
	"encoding/base64"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"

	"github.com/wailsapp/wails/v2/pkg/runtime"

	"paper-scan-processor/backend/drive"
	"paper-scan-processor/backend/filetree"
	"paper-scan-processor/backend/pdf"
)

// App struct
type App struct {
	ctx context.Context

	// uploadCancels holds the cancel func for each localPath currently
	// mid-upload, so CancelUpload (called from a separate RPC invocation,
	// concurrently with the in-flight UploadFile call) can abort it.
	uploadMu      sync.Mutex
	uploadCancels map[string]context.CancelFunc
}

// NewApp creates a new App application struct
func NewApp() *App {
	return &App{uploadCancels: make(map[string]context.CancelFunc)}
}

// recoverToErr recovers from a panic in a deferred call and assigns it to
// *err, so a bug in one RPC method surfaces to the frontend as a rejected
// promise instead of crashing the whole process.
func recoverToErr(err *error) {
	if r := recover(); r != nil {
		*err = fmt.Errorf("recovered from panic: %v", r)
	}
}

// startup is called when the app starts. The context is saved
// so we can call the runtime methods
func (a *App) startup(ctx context.Context) {
	a.ctx = ctx
}

// OpenPDF shows a file-open dialog filtered to PDFs and returns the selected path.
// Returns an empty string if the user cancels.
func (a *App) OpenPDF() (path string, err error) {
	defer recoverToErr(&err)
	path, err = runtime.OpenFileDialog(a.ctx, runtime.OpenDialogOptions{
		Title: "Open PDF",
		Filters: []runtime.FileFilter{
			{DisplayName: "PDF Files (*.pdf)", Pattern: "*.pdf"},
		},
	})
	return path, err
}

// PageCount returns the number of pages in the PDF at path.
func (a *App) PageCount(path string) (n int, err error) {
	defer recoverToErr(&err)
	return pdf.PageCount(path)
}

// RenderPage renders a single page of the PDF at path as a PNG and returns it
// base64-encoded. widthPx controls the output width; height is scaled proportionally.
func (a *App) RenderPage(path string, pageNum int, widthPx int) (encoded string, err error) {
	defer recoverToErr(&err)
	tmpDir, err := os.MkdirTemp("", "psp-render-*")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(tmpDir)

	outPrefix := filepath.Join(tmpDir, "page")
	page := strconv.Itoa(pageNum)

	out, err := exec.Command(
		"pdftoppm",
		"-f", page,
		"-l", page,
		"-singlefile",
		"-png",
		"-scale-to-x", strconv.Itoa(widthPx),
		"-scale-to-y", "-1",
		path,
		outPrefix,
	).CombinedOutput()
	if err != nil {
		return "", fmt.Errorf("pdftoppm: %w\n%s", err, out)
	}

	data, err := os.ReadFile(outPrefix + ".png")
	if err != nil {
		return "", err
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// SavePDF shows a save-file dialog filtered to PDFs and returns the chosen path.
// Returns an empty string if the user cancels.
func (a *App) SavePDF() (path string, err error) {
	defer recoverToErr(&err)
	path, err = runtime.SaveFileDialog(a.ctx, runtime.SaveDialogOptions{
		Title:           "Save Merged PDF",
		DefaultFilename: "merged.pdf",
		Filters: []runtime.FileFilter{
			{DisplayName: "PDF Files (*.pdf)", Pattern: "*.pdf"},
		},
	})
	if err != nil || path == "" {
		return path, err
	}
	if !strings.HasSuffix(strings.ToLower(path), ".pdf") {
		path += ".pdf"
	}
	return path, nil
}

// OpenFile opens the file at path with the system default application.
func (a *App) OpenFile(path string) (err error) {
	defer recoverToErr(&err)
	return exec.Command("open", path).Run()
}

// DeleteFile removes the file at path.
func (a *App) DeleteFile(path string) (err error) {
	defer recoverToErr(&err)
	return os.Remove(path)
}

// MergePDFs interleaves pages from pathA and pathB and writes the result to outPath.
func (a *App) MergePDFs(pathA, pathB, outPath string, firstPageInA, reverseB bool, skipA, skipB []int, rotationsA, rotationsB map[int]int) (err error) {
	defer recoverToErr(&err)
	return pdf.MergePDFs(pathA, pathB, outPath, firstPageInA, reverseB, skipA, skipB, rotationsA, rotationsB)
}

// PickFolder shows a folder-select dialog with the given title and returns
// the chosen path. Returns an empty string if the user cancels.
func (a *App) PickFolder(title string) (path string, err error) {
	defer recoverToErr(&err)
	return runtime.OpenDirectoryDialog(a.ctx, runtime.OpenDialogOptions{
		Title: title,
	})
}

// ScanLocalRoot recursively scans root and returns it as a LocalFileGroup
// tree (nested to match the folder structure), with size and page count
// metadata for each file.
func (a *App) ScanLocalRoot(root string) (group filetree.LocalFileGroup, err error) {
	defer recoverToErr(&err)
	return filetree.ScanLocalRoot(root)
}

// ListDriveFolder returns the direct children of the Drive folder with the
// given ID ("root" for the top level of My Drive), folders first then
// files. Triggers the OAuth flow on first use if no token is cached yet.
func (a *App) ListDriveFolder(folderID string) (items []drive.Item, err error) {
	defer recoverToErr(&err)
	return drive.ListFolder(a.ctx, folderID)
}

// UploadFile uploads the local file at localPath to the Drive folder with
// the given ID, naming it name on Drive. Returns the ID of the created
// Drive file.
func (a *App) UploadFile(localPath, folderID, name string) (id string, err error) {
	defer recoverToErr(&err)
	return drive.UploadFile(a.ctx, localPath, folderID, name)
}

// outputFileDest returns the destination path for the i-th pdf.OutputFileSpec.
func outputFileDest(files []pdf.OutputFileSpec, i int) string {
	name := strings.TrimSpace(files[i].Name)
	if name == "" {
		name = fmt.Sprintf("output-%d", i+1)
	}
	if !strings.HasSuffix(strings.ToLower(name), ".pdf") {
		name += ".pdf"
	}
	return filepath.Join(files[i].OutDir, name)
}

// CheckConflicts returns the destination paths that already exist on disk.
func (a *App) CheckConflicts(files []pdf.OutputFileSpec) (conflicts []string, err error) {
	defer recoverToErr(&err)
	conflicts = []string{}
	for i := range files {
		dest := outputFileDest(files, i)
		if _, err := os.Stat(dest); err == nil {
			conflicts = append(conflicts, dest)
		}
	}
	return conflicts, nil
}

// ExportSplit splits the PDF at inPath according to files and writes each
// segment to its OutDir using its Name.
// Each file's Pages lists the original (1-indexed) page numbers in display
// order; skip filtering and reordering have already been applied by the caller.
// rotations maps 1-indexed page numbers to clockwise degrees (90, 180, 270).
func (a *App) ExportSplit(inPath string, files []pdf.OutputFileSpec, rotations map[int]int) (err error) {
	defer recoverToErr(&err)
	tmpDir, err := os.MkdirTemp("", "psp-split-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	paths, err := pdf.SplitPDF(inPath, files, rotations, tmpDir)
	if err != nil {
		return err
	}

	for i, src := range paths {
		if err := pdf.CopyFile(src, outputFileDest(files, i)); err != nil {
			return err
		}
	}
	return nil
}

import { useEffect, useState } from 'react'
import { UploadFile } from '../../../wailsjs/go/main/App'

export type UploadStatus = 'idle' | 'queued' | 'uploading' | 'done' | 'error'

export interface UploadJob {
  path: string
  folderId: string
  name: string
}

export interface UploadEntry extends UploadJob {
  status: UploadStatus
  error?: string
}

// Per-file upload status, driven by a sequential (concurrency = 1) worker.
// A module-level singleton (like ../../lib/pageCache) rather than a hook:
// there is only ever one upload run in flight for the app, so the queue's
// lifetime doesn't need to be tied to any one component instance. Callers
// resolve each file's destination folder/name up front and pass in an
// ordered list of jobs — this module only knows how to run them one at a
// time and track status, not about the file tree or Drive assignments.
const filesByPath = new Map<string, UploadEntry>()
let pendingPaths: string[] = []
const listeners = new Set<() => void>()
let running = false
let cancelled = false

function notify() {
  for (const fn of listeners) fn()
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

export function useUploadQueueRender() {
  const [, setTick] = useState(0)
  useEffect(() => subscribe(() => setTick(t => t + 1)), [])
}

export function getStatus(path: string): UploadEntry | undefined {
  return filesByPath.get(path)
}

// True once none of the given files are still queued or uploading — i.e.
// each has either reached a terminal state (done/error) or was never
// started. Callers use this to know when it's safe to let the upload
// modal close.
export function hasSettled(paths: string[]): boolean {
  return !paths.some(path => {
    const status = filesByPath.get(path)?.status
    return status === 'queued' || status === 'uploading'
  })
}

function updateStatus(path: string, status: UploadStatus, error?: string) {
  const existing = filesByPath.get(path)!
  filesByPath.set(path, { ...existing, status, error })
  notify()
}

async function runQueue() {
  if (running) return
  running = true
  while (!cancelled && pendingPaths.length > 0) {
    const path = pendingPaths.shift()!
    const job = filesByPath.get(path)!
    updateStatus(path, 'uploading')
    try {
      await UploadFile(job.path, job.folderId, job.name)
      updateStatus(path, 'done')
    } catch (e) {
      updateStatus(path, 'error', String(e))
    }
  }
  running = false
}

function enqueue(newJobs: UploadJob[]) {
  if (newJobs.length === 0) return
  cancelled = false
  for (const job of newJobs) {
    filesByPath.set(job.path, { ...job, status: 'queued', error: undefined })
    pendingPaths.push(job.path)
  }
  notify()
  void runQueue()
}

export function start(newJobs: UploadJob[]): void {
  enqueue(newJobs)
}

export function retry(job: UploadJob): void {
  enqueue([job])
}

// Stops starting new files; does not abort an in-flight request. Files
// still waiting their turn go back to idle since they were never attempted.
export function cancelRemaining(): void {
  cancelled = true
  for (const path of pendingPaths) updateStatus(path, 'idle')
  pendingPaths = []
}

export function reset(): void {
  if (!hasSettled(Array.from(filesByPath.keys()))) {
    // Callers must only invoke this once hasSettled() is true for all files;
    // otherwise a request from the discarded run could still be in flight and
    // would resurface after this call.
    throw new Error('reset() called while an upload is still in flight')
  }
  cancelled = false
  running = false
  filesByPath.clear()
  pendingPaths = []
  notify()
}

